import{c as d,Q as r,j as a,m as o}from"./chunks/framework.B2dUnTNU.js";const c=JSON.parse('{"title":"B42 职业排名","description":"","frontmatter":{},"headers":[],"relativePath":"b42/occupations-tier.md","filePath":"b42/occupations-tier.md","lastUpdated":1779624442000}'),n={name:"b42/occupations-tier.md"};function s(e,t,h,g,l,b){return r(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="b42-职业排名" tabindex="-1">B42 职业排名 <a class="header-anchor" href="#b42-职业排名" aria-label="Permalink to &quot;B42 职业排名&quot;">​</a></h1><p>基于 B42 当前版本的 meta，综合考虑<strong>战斗力、经济性、B42 新机制适配度</strong>做排名。重点标注 B42.16 的职业改动。</p><hr><h2 id="b42-职业变化-b42-16-更新" tabindex="-1">B42 职业变化（B42.16 更新） <a class="header-anchor" href="#b42-职业变化-b42-16-更新" aria-label="Permalink to &quot;B42 职业变化（B42.16 更新）&quot;">​</a></h2><p>在排名之前，先看和 B41 相比的关键职业变化：</p><table tabindex="0"><thead><tr><th>职业</th><th>B41 状态</th><th>B42 变化</th></tr></thead><tbody><tr><td><strong>木匠</strong></td><td>+3 木工</td><td>比以前值钱——拆解不给木工经验了，开局高木工让你直接造高级结构</td></tr><tr><td><strong>建筑工</strong></td><td>+3 短棍, +1 木工</td><td>钝器熟练现在<strong>分开</strong>了短棍和长棍，更精确</td></tr><tr><td><strong>护士</strong></td><td>+2 急救, +1 轻手轻脚</td><td>新增<strong>夜猫子特征内置</strong>（值夜班理当如此）</td></tr><tr><td><strong>退伍兵</strong></td><td>从不恐慌</td><td>现在<strong>还忽略不适感</strong>，增益</td></tr><tr><td><strong>所有职业</strong></td><td>开局需看电视练级</td><td>职业起点技能更高，<strong>不依赖早期电视冲级</strong></td></tr></tbody></table><h3 id="新特征-b42-16" tabindex="-1">新特征（B42.16） <a class="header-anchor" href="#新特征-b42-16" aria-label="Permalink to &quot;新特征（B42.16）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>效果</th><th>点耗</th></tr></thead><tbody><tr><td><strong>能工巧匠</strong></td><td>增加维护技能</td><td>可选</td></tr><tr><td><strong>射击爱好者</strong></td><td>增加瞄准技能</td><td>可选</td></tr></tbody></table><hr><h2 id="排名总览" tabindex="-1">排名总览 <a class="header-anchor" href="#排名总览" aria-label="Permalink to &quot;排名总览&quot;">​</a></h2><h3 id="s-档-—-版本答案" tabindex="-1">S 档 — 版本答案 <a class="header-anchor" href="#s-档-—-版本答案" aria-label="Permalink to &quot;S 档 — 版本答案&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>核心优势</th><th>B42 适配</th></tr></thead><tbody><tr><td>🥇 <strong>伐木工</strong></td><td>0</td><td><strong>斧头专精</strong>（+25% 斧头挥速+砍树速度）, +2 斧头, +1 力量</td><td>斧类武器始终顶级，0 成本福利之王</td></tr><tr><td>🥈 <strong>退伍兵</strong></td><td>-8</td><td><strong>从不恐慌</strong>（永不恐慌 + 现在也忽略不适感）, +2 瞄准, +2 装弹</td><td>B42 增益：不适感免疫让重甲角色受益</td></tr><tr><td>🥉 <strong>大盗</strong></td><td>-6</td><td><strong>可以直接接电发动车辆</strong>, +2 灵活/+2 潜行/+2 轻手轻脚</td><td>接电发车仍是游戏中最稀缺的早期能力，灵活对战斗机动性极关键</td></tr></tbody></table><h3 id="a-档-—-强力选择" tabindex="-1">A 档 — 强力选择 <a class="header-anchor" href="#a-档-—-强力选择" aria-label="Permalink to &quot;A 档 — 强力选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>核心优势</th><th>B42 适配</th></tr></thead><tbody><tr><td><strong>消防员</strong></td><td>0</td><td>+1 斧头/+1 体格/+1 冲刺/+1 力量</td><td>全面且 0 成本，开局就是强化版平民</td></tr><tr><td><strong>修理工</strong></td><td>-4</td><td><strong>+2 维护</strong>, +1 木工, +1 短棍</td><td>维护在 B42 极度重要——武器寿命+自制物品耐久</td></tr><tr><td><strong>木匠</strong></td><td>+2</td><td><strong>+3 木工</strong></td><td>拆解不给木工经验后，开局高木工价值飙升</td></tr><tr><td><strong>建筑工</strong></td><td>-2</td><td>+3 短棍, +1 木工</td><td>B42.16 后短棍/长棍技能分开，定位更清晰</td></tr><tr><td><strong>机械师</strong></td><td>-4</td><td><strong>业余机械师</strong>, +3 机械, +1 短棍</td><td>车辆仍是生存核心，专业机械师价值不减</td></tr></tbody></table><h3 id="b-档-—-可选" tabindex="-1">B 档 — 可选 <a class="header-anchor" href="#b-档-—-可选" aria-label="Permalink to &quot;B 档 — 可选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>核心优势</th><th>说明</th></tr></thead><tbody><tr><td><strong>警察</strong></td><td>-4</td><td>+3 瞄准, +1 灵活, +2 装弹</td><td>枪械角色，但枪声引怪是硬伤。灵活价值高</td></tr><tr><td><strong>保安</strong></td><td>-2</td><td><strong>夜猫子</strong>, +1 轻手轻脚, +2 冲刺</td><td>便宜好用，夜猫子适合夜间作业</td></tr><tr><td><strong>公园管理员</strong></td><td>-4</td><td>+1 斧头, +1 木工, +2 采集, +2 诱捕</td><td>B42 荒野生存 + 狩猎系统让户外职业更实用</td></tr><tr><td><strong>健身教练</strong></td><td>-6</td><td><strong>营养学家</strong>, +3 体格, +2 冲刺</td><td>体格对肌肉疲劳系统有直接帮助</td></tr><tr><td><strong>厨师</strong></td><td>-4</td><td><strong>厨师</strong>, +3 烹饪, +1 维护, +1 短刀</td><td>B42 烹饪系统重做 + 食物保存 = 厨师价值上升</td></tr><tr><td><strong>汉堡店员工</strong></td><td>+2</td><td><strong>厨师</strong>, +2 烹饪, +1 维护, +1 短刀</td><td>最便宜获得维护的方式（反赚 2 点），性价比之王</td></tr><tr><td><strong>电工</strong></td><td>-4</td><td>+3 电工</td><td>发电机能力，但杂志也能解决</td></tr><tr><td><strong>工程师</strong></td><td>-4</td><td>+1 木工, +1 电工</td><td>配方独特（炸弹/陷阱），娱乐性大于实用</td></tr></tbody></table><h3 id="c-档-—-不推荐-除非角色扮演" tabindex="-1">C 档 — 不推荐（除非角色扮演） <a class="header-anchor" href="#c-档-—-不推荐-除非角色扮演" aria-label="Permalink to &quot;C 档 — 不推荐（除非角色扮演）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>原因</th></tr></thead><tbody><tr><td><strong>医生</strong></td><td>+2</td><td>急救是游戏中最没用的技能——被咬了 100% 死，小伤随便处理</td></tr><tr><td><strong>护士</strong></td><td>+2</td><td>急救 + 轻手轻脚 + 内置夜猫子。比医生好一点但仍然一般</td></tr><tr><td><strong>农民</strong></td><td>+2</td><td>农耕是最容易练的技能之一，不值得用职业点</td></tr><tr><td><strong>渔夫</strong></td><td>-2</td><td>钓鱼重做后更互动，但技能本身容易练，不必占职业位</td></tr><tr><td><strong>金属工</strong></td><td>-6</td><td>锻造线需要大量前置投入，开局选金属工不如后期转职</td></tr></tbody></table><h3 id="特殊-—-自定义" tabindex="-1">特殊 — 自定义 <a class="header-anchor" href="#特殊-—-自定义" aria-label="Permalink to &quot;特殊 — 自定义&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>费用</th><th>说明</th></tr></thead><tbody><tr><td><strong>失业</strong></td><td>+8</td><td>8 点自由分配，配合版本最强负面特征可凑出暴力开局</td></tr></tbody></table><hr><h2 id="b42-职业选择策略" tabindex="-1">B42 职业选择策略 <a class="header-anchor" href="#b42-职业选择策略" aria-label="Permalink to &quot;B42 职业选择策略&quot;">​</a></h2><h3 id="b42-的环境变化对职业的影响" tabindex="-1">B42 的环境变化对职业的影响 <a class="header-anchor" href="#b42-的环境变化对职业的影响" aria-label="Permalink to &quot;B42 的环境变化对职业的影响&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>肌肉疲劳 → 轻型武器开局更有吸引力（保安、汉堡店员工）</span></span>
<span class="line"><span>锻造系统 → 维护和木工价值大增（修理工、木匠）</span></span>
<span class="line"><span>荒野扩展 → 户外技能不再纯娱乐（公园管理员）</span></span>
<span class="line"><span>烹饪重做 → 厨师和汉堡店员工不再是凑数职业</span></span>
<span class="line"><span>光照重做 → 夜猫子从&quot;还行&quot;变&quot;实用&quot;</span></span></code></pre></div><h3 id="推荐开局路线" tabindex="-1">推荐开局路线 <a class="header-anchor" href="#推荐开局路线" aria-label="Permalink to &quot;推荐开局路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>玩法风格</th><th>推荐职业</th><th>搭配</th></tr></thead><tbody><tr><td><strong>新手保险</strong></td><td>修理工 + 正面特征</td><td>维护 +2 让武器活更久</td></tr><tr><td><strong>战斗狂</strong></td><td>伐木工 + 速度特征</td><td>斧头专精 + 高体格 = 砍瓜切菜</td></tr><tr><td><strong>枪械流</strong></td><td>退伍兵 + 射击爱好者</td><td>不恐慌不不适，站桩输出</td></tr><tr><td><strong>潜行流</strong></td><td>大盗 + 轻量特征</td><td>接电发车 + 高机动</td></tr><tr><td><strong>锻造流</strong></td><td>修理工 或 木匠</td><td>制作专注，维护/木工打底</td></tr><tr><td><strong>荒野流</strong></td><td>公园管理员 + 户外特征</td><td>采集 + 诱捕 + 新狩猎系统</td></tr></tbody></table><hr><h2 id="特征搭配建议" tabindex="-1">特征搭配建议 <a class="header-anchor" href="#特征搭配建议" aria-label="Permalink to &quot;特征搭配建议&quot;">​</a></h2><h3 id="b42-特别推荐的正向特征" tabindex="-1">B42 特别推荐的正向特征 <a class="header-anchor" href="#b42-特别推荐的正向特征" aria-label="Permalink to &quot;B42 特别推荐的正向特征&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>理由</th></tr></thead><tbody><tr><td><strong>能工巧匠</strong> (新)</td><td>加维护——B42 最重要的技能之一</td></tr><tr><td><strong>勇敢</strong></td><td>减少恐慌，退伍兵下位替代</td></tr><tr><td><strong>强壮</strong></td><td>力量增加负重和伤害，肌肉疲劳下更有价值</td></tr><tr><td><strong>运动健将</strong></td><td>体格直接影响武器挥舞可持续时间</td></tr><tr><td><strong>猫眼</strong></td><td>B42 光照重做后夜视能力价值飞升</td></tr><tr><td><strong>灵巧</strong></td><td>物资转移加速，永远是好的</td></tr><tr><td><strong>浅眠</strong></td><td>减少睡眠需求，更多时间干活</td></tr></tbody></table><h3 id="b42-推荐负面特征" tabindex="-1">B42 推荐负面特征 <a class="header-anchor" href="#b42-推荐负面特征" aria-label="Permalink to &quot;B42 推荐负面特征&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特征</th><th>给点</th><th>B42 还值不值</th></tr></thead><tbody><tr><td><strong>吸烟者</strong></td><td>+4</td><td>⚠️ B42 已削弱，不再是&quot;免费点&quot;。但烟草可以自己种了</td></tr><tr><td><strong>口渴</strong></td><td>+6</td><td>仍然安全，水源管理不变</td></tr><tr><td><strong>弱胃</strong></td><td>+3</td><td>仍然安全（别吃变质食物就行）</td></tr><tr><td><strong>近视</strong></td><td>+2</td><td>仍然可用，采集惩罚可接受</td></tr><tr><td><strong>缓慢愈合</strong></td><td>+6</td><td>安全，反正被咬了都是死</td></tr><tr><td><strong>薄皮</strong></td><td>+8</td><td>高风险，被咬=死，但老玩家可控</td></tr><tr><td><strong>容易生病</strong></td><td>+4</td><td>B42 天气更复杂，略增风险</td></tr><tr><td><strong>慢速阅读</strong></td><td>+2</td><td>⚠️ B42 技能书更重要了，<strong>不推荐了</strong></td></tr></tbody></table>`,32)])])}const u=d(n,[["render",s]]);export{c as __pageData,u as default};
